COPY (SELECT system,origin,message,regexp_replace(path, '\[[0-9]+\]', '[*]', 'g') AS path,param_key,display_name,choice_of,discriminators,count(*) n_occurrences FROM param_occurrence WHERE project_id='4b7bfd50ddb6' AND param_key IS NOT NULL AND NOT ((CASE WHEN path LIKE '%/logicalChannelConfig/%/logicalChannelGroup' THEN false WHEN regexp_replace(path, '\[[0-9]+\]', '[*]', 'g') IN ('systemInformationBlockType1/cellAccessRelatedInfo/cellIdentity','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mcc','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mnc','systemInformationBlockType1/cellAccessRelatedInfo/trackingAreaCode') THEN true ELSE COALESCE(is_identifier,false) END) OR regexp_replace(path,'^.*/','') ~ '^(spare[0-9]*|dummy|reserved)$' OR path IN ('systemFrameNumber','mib/systemFrameNumber')) GROUP BY system,origin,message,regexp_replace(path, '\[[0-9]+\]', '[*]', 'g'),param_key,display_name,choice_of,discriminators ORDER BY system,origin,message,regexp_replace(path, '\[[0-9]+\]', '[*]', 'g'),param_key,display_name,choice_of,discriminators) TO STDOUT WITH CSV HEADER;
